11	// 本文件钉住“主动结束未确认轮次”的原子落盘回归保障。
12	//
13	// 场景：节点已有一块确认历史（第 1 轮确认，当前处于第 2 轮）。第 2 轮的本地
14	// 提议与一个竞争候选均已登记，两者引用的交易中有共享交易，也有仅被单个候选
15	// 引用的交易；两名验证者分别投给两个候选但都未达确认门槛（四验证者门槛为
16	// 3 票）。池内另有未被任何候选引用的排队交易（因序号缺口而未被本地提议打包）。
17	// 各交易到期轮次覆盖“恰好等于下一轮（2→3 后失效）”与“晚于下一轮（2→3 后
18	// 仍排队）”两种情况，使结束轮次确实同时涉及回到排队与过期两种结果。
19	//
20	// 当这次 EndRound 因节点状态写入失败而返回错误时：返回轮次值必须为 0；
21	// 候选落选标记、交易回到排队、轮次前进与到期失效作为一次完整操作必须整体不
22	// 生效——等待投票的交易不提前回排队，排队中的交易不提前过期，确认历史、
23	// 账户已确认序号、待处理交易与缺口说明全部保持操作前结果；磁盘状态文件逐字节
24	// 不变、不残留临时文件，重开节点看到同样的未结束状态。
25	//
26	// 保存恢复正常后，在仍处于原轮次的节点上再次 EndRound 才进入下一轮：
27	// 旧轮明确标记未确认结束、两候选均落选、原投票仍可查询；未到期的候选交易
28	// 回到排队（被两个候选共享的交易只保留一个池位）；到期轮次不大于新轮次的
29	// 交易从待处理列表移除并可查为 expired——共享的、竞争候选独有的、以及此前
30	// 没有被候选引用的交易都包括在内；此次结束不增加确认块、不推进账户已确认
31	// 序号。本组测试不改变现有公开入口、候选规则与确认门槛。
32	
33	// maxTestTxs 固定为 3：第 2 轮池中有四笔可打包交易分属四个账户，费用最低的
34	// 一笔被排除在本地提议之外，恰好只能通过 RegisterCandidate 进入竞争候选。
35	const maxTestTxs = 3
36	
37	// round2Tx 描述第 2 轮场景中的一笔交易及其候选归属。
38	type round2Tx struct {
39		tx *Transaction
40		// InLocal/InAlt 标记该交易是否被本地提议/竞争候选引用。
41		InLocal bool
42		InAlt   bool
43	}
44	
45	// buildRoundTwoPending 在第 1 轮确认历史之上构造第 2 轮未决场景。
46	//
47	// 交易布局（账户0 第 1 轮已确认 seq1，其余账户确认序号为 0；账户4 不是
48	// 验证者，仅作发送者，其 seq2/seq3 因缺少 seq1 形成序号缺口、不会被打包）：
49	//
50	//	shared      账户0 seq2 fee10 expiry=3   本地+竞争 共享，恰好下一轮到期 -> 过期
51	//	localOnly   账户1 seq1 fee20 expiry=100 仅本地提议，晚到期           -> 回排队
52	//	altOnly     账户2 seq1 fee5  expiry=3   仅竞争候选，恰好下一轮到期   -> 过期
53	//	sharedLate  账户3 seq1 fee40 expiry=100 本地+竞争 共享，晚到期       -> 回排队
54	//	queuedExpire 账户4 seq2 fee1 expiry=3   候选外排队（带缺口）         -> 过期
55	//	queuedLate  账户4 seq3 fee1 expiry=100  候选外排队（带缺口）         -> 仍排队
56	//
57	// 单块上限为 3，本地提议按费用取 sharedLate、localOnly、shared 三笔；
58	// altOnly 费用最低、留在池内排队，只被竞争候选引用。
59	func buildRoundTwoPending(t *testing.T, n *Node, keys []testKey) (ProposalView, string, []round2Tx) {
60		t.Helper()
61		txs := []round2Tx{
62			{tx: NewTransaction(keys[0].priv, 2, []byte("shared"), 10, 3), InLocal: true, InAlt: true},
63			{tx: NewTransaction(keys[1].priv, 1, []byte("local-only"), 20, 100), InLocal: true},
64			{tx: NewTransaction(keys[2].priv, 1, []byte("alt-only"), 5, 3), InAlt: true},
65			{tx: NewTransaction(keys[3].priv, 1, []byte("shared-late"), 40, 100), InLocal: true, InAlt: true},
66			{tx: NewTransaction(keys[4].priv, 2, []byte("queued-expire"), 1, 3)},
67			{tx: NewTransaction(keys[4].priv, 3, []byte("queued-late"), 1, 100)},
68		}
69		for _, x := range txs {
70			if _, err := n.Submit(x.tx); err != nil {
71				t.Fatalf("submit %q: %v", x.tx.Content, err)
72			}
73		}
74	
75		local, err := n.Propose()
76		if err != nil {
77			t.Fatal(err)
78		}
79		// 打包顺序只取决于费用：sharedLate(40)、localOnly(20)、shared(10)，
80		// 取满上限 3 笔；altOnly(5) 落选，queuedExpire/queuedLate 受序号缺口阻挡。
81		wantLocal := []string{txs[3].tx.ID(), txs[1].tx.ID(), txs[0].tx.ID()}
82		if fmt.Sprint(local.TxIDs) != fmt.Sprint(wantLocal) {
83			t.Fatalf("setup: local proposal order = %v, want %v", local.TxIDs, wantLocal)
84		}
85	
86		// 竞争候选：竞争独有交易在前，两笔共享交易居中/收尾，顺序与本地提议不同。
87		altList := []string{txs[2].tx.ID(), txs[0].tx.ID(), txs[3].tx.ID()}
88		alt, err := n.RegisterCandidate(2, altList)
89		if err != nil {
90			t.Fatal(err)
91		}
92		if alt.BlockID == local.BlockID {
93			t.Fatal("setup: competitor block id must differ from local proposal")
94		}
95	
96		// 验证者0 投本地、验证者1 投竞争候选，各 1 票；验证者2、3 未投票，均未决。
97		if res, err := n.Vote(keys[0].pub, 2, local.BlockID); err != nil || !res.Counted || res.Confirmed {
98			t.Fatalf("local proposal vote: %+v %v", res, err)
99		}
100		if res, err := n.Vote(keys[1].pub, 2, alt.BlockID); err != nil || !res.Counted || res.Confirmed {
101			t.Fatalf("competitor vote: %+v %v", res, err)
102		}
103		return local, alt.BlockID, txs
104	}
