115	// assertConfirmedHistory 断言第 1 轮确认历史未被后续操作改写：高度仍为 1、
116	// 最新块即给定块；第 1 轮候选记录保留、唯一候选胜出且三张确认票仍在。
117	func assertConfirmedHistory(t *testing.T, n *Node, confirmedBlock Block, keys []testKey) {
118		t.Helper()
119		if n.Height() != 1 {
120			t.Fatalf("confirmed height = %d, want 1", n.Height())
121		}
122		blk, err := n.BlockAt(1)
123		if err != nil {
124			t.Fatal(err)
125		}
126		assertSameBlock(t, "block at height 1", blk, confirmedBlock)
127		if latest, ok := n.LatestBlock(); !ok {
128			t.Fatal("latest confirmed block disappeared")
129		} else {
130			assertSameBlock(t, "latest block", latest, confirmedBlock)
131		}
132		if _, err := n.BlockAt(2); reason(err) != ReasonUnknownBlock {
133			t.Fatalf("block at height 2: %v, want %s", err, ReasonUnknownBlock)
134		}
135		rc1, err := n.Candidates(1)
136		if err != nil {
137			t.Fatal(err)
138		}
139		if !rc1.Ended || rc1.UnconfirmedEnd || !rc1.HasRecords || len(rc1.Candidates) != 1 {
140			t.Fatalf("round 1 confirmed history changed: %+v", rc1)
141		}
142		won := rc1.Candidates[0]
143		if won.Result != CandidateWon || won.BlockID != confirmedBlock.ID || len(won.Voters) != 3 {
144			t.Fatalf("round 1 winner record changed: %+v", won)
145		}
146	}
147	
148	// assertRoundTwoPending 断言节点正处于第 2 轮结束前/失败后的完整未决状态：
149	// 轮次未前进；本地提议标识与交易顺序、两候选的 pending 结果、已有投票与未投票
150	// 名单原样；候选内四笔交易仍 waiting-vote（不提前回排队），候选外两笔仍
151	// waiting-pack（不提前过期）；账户确认序号、待处理集合与缺口说明保持操作前结果。
152	func assertRoundTwoPending(t *testing.T, n *Node, local ProposalView, altID string, txs []round2Tx, confirmedBlock Block, keys []testKey) {
153		t.Helper()
154	
155		if n.CurrentRound() != 2 {
156			t.Fatalf("current round = %d, want 2", n.CurrentRound())
157		}
158		assertConfirmedHistory(t, n, confirmedBlock, keys)
159	
160		rc, err := n.Candidates(2)
161		if err != nil {
162			t.Fatal(err)
163		}
164		if rc.Ended || rc.UnconfirmedEnd || !rc.HasRecords {
165			t.Fatalf("round 2 must stay pending with records: %+v", rc)
166		}
167		if len(rc.Candidates) != 2 {
168			t.Fatalf("candidate count = %d, want 2", len(rc.Candidates))
169		}
170		wantUnvoted := [][]byte{keys[2].pub, keys[3].pub}
171		if fmt.Sprint(hexKeys(rc.Unvoted)) != fmt.Sprint(hexKeys(wantUnvoted)) {
172			t.Fatalf("unvoted validators = %x, want %x", rc.Unvoted, wantUnvoted)
173		}
174	
175		var gotLocal, gotAlt *CandidateView
176		for i := range rc.Candidates {
177			switch rc.Candidates[i].BlockID {
178			case local.BlockID:
179				gotLocal = &rc.Candidates[i]
180			case altID:
181				gotAlt = &rc.Candidates[i]
182			}
183		}
184		if gotLocal == nil || gotAlt == nil {
185			t.Fatalf("both candidates must remain present: %+v", rc.Candidates)
186		}
187		wantLocalOrder := []string{txs[3].tx.ID(), txs[1].tx.ID(), txs[0].tx.ID()}
188		if !gotLocal.Local || gotLocal.Result != CandidatePending ||
189			fmt.Sprint(gotLocal.TxIDs) != fmt.Sprint(wantLocalOrder) ||
190			len(gotLocal.Voters) != 1 || fmt.Sprintf("%x", gotLocal.Voters[0]) != fmt.Sprintf("%x", keys[0].pub) {
191			t.Fatalf("local candidate must stay pending with its order and single vote: %+v", gotLocal)
192		}
193		wantAltOrder := []string{txs[2].tx.ID(), txs[0].tx.ID(), txs[3].tx.ID()}
194		if gotAlt.Local || gotAlt.Result != CandidatePending ||
195			fmt.Sprint(gotAlt.TxIDs) != fmt.Sprint(wantAltOrder) ||
196			len(gotAlt.Voters) != 1 || fmt.Sprintf("%x", gotAlt.Voters[0]) != fmt.Sprintf("%x", keys[1].pub) {
197			t.Fatalf("competitor must stay pending with its order and single vote: %+v", gotAlt)
198		}
199	
200		// 本地提议视图始终返回同一份标识与交易顺序。
201		p, ok := n.Proposal()
202		if !ok {
203			t.Fatal("local proposal must still be available after the failed end")
204		}
205		if p.Round != 2 || p.BlockID != local.BlockID || fmt.Sprint(p.TxIDs) != fmt.Sprint(wantLocalOrder) {
206			t.Fatalf("local proposal changed: %+v, want id=%s order=%v", p, local.BlockID, wantLocalOrder)
207		}
208	
209		// 候选内交易保持 proposed，候选外保持 queued；都不得关联确认块。
210		for _, x := range txs {
211			info := n.mustTx(t, x.tx.ID())
212			want := StatusQueued
213			if x.InLocal || x.InAlt {
214				want = StatusProposed
215			}
216			if info.Status != want {
217				t.Fatalf("tx %q status = %s, want %s", x.tx.Content, info.Status, want)
218			}
219			if info.BlockHeight != 0 || info.BlockID != "" {
220				t.Fatalf("tx %q must not reference a block: height=%d block=%q",
221					x.tx.Content, info.BlockHeight, info.BlockID)
222			}
223		}
224	
225		// 账户查询：确认序号、待处理交易与缺口说明全部保持操作前结果。
226		assertAccountQueue(t, n, keys[0].pub, 1, map[string]string{txs[0].tx.ID(): "waiting-vote"})
227		if a := n.Account(keys[0].pub); a.Gap != 0 {
228			t.Fatalf("account 0 gap = %d, want 0", a.Gap)
229		}
230		assertAccountQueue(t, n, keys[1].pub, 0, map[string]string{txs[1].tx.ID(): "waiting-vote"})
231		assertAccountQueue(t, n, keys[2].pub, 0, map[string]string{txs[2].tx.ID(): "waiting-vote"})
232		assertAccountQueue(t, n, keys[3].pub, 0, map[string]string{txs[3].tx.ID(): "waiting-vote"})
233		// 账户4 两笔候选外排队交易均 waiting-pack；缺少 seq1，最早缺口为 1。
234		assertAccountQueue(t, n, keys[4].pub, 0, map[string]string{
235			txs[4].tx.ID(): "waiting-pack",
236			txs[5].tx.ID(): "waiting-pack",
237		})
238		if a := n.Account(keys[4].pub); a.Gap != 1 {
239			t.Fatalf("account 4 gap = %d, want 1", a.Gap)
240		}
241	}
242	
243	// assertRoundThreeEnded 断言保存恢复后再次 EndRound 成功进入第 3 轮后的状态。
244	func assertRoundThreeEnded(t *testing.T, n *Node, local ProposalView, altID string, txs []round2Tx, confirmedBlock Block, keys []testKey) {
245		t.Helper()
246		const newRound = uint64(3)
247	
248		if n.CurrentRound() != newRound {
249			t.Fatalf("current round = %d, want 3", n.CurrentRound())
250		}
251		// 主动结束不留确认块：高度与确认历史完全不变，也不存在高度 2 的块。
252		assertConfirmedHistory(t, n, confirmedBlock, keys)
253	
254		// 旧轮明确标记未确认结束，两候选均落选，原投票与未投票名单仍可查询。
255		rc, err := n.Candidates(2)
256		if err != nil {
257			t.Fatal(err)
258		}
259		if !rc.Ended || !rc.UnconfirmedEnd || !rc.HasRecords {
260			t.Fatalf("round 2 must be an unconfirmed ended round with records: %+v", rc)
261		}
262		wantUnvoted := [][]byte{keys[2].pub, keys[3].pub}
263		if fmt.Sprint(hexKeys(rc.Unvoted)) != fmt.Sprint(hexKeys(wantUnvoted)) {
264			t.Fatalf("unvoted validators = %x, want %x", rc.Unvoted, wantUnvoted)
265		}
266		if len(rc.Candidates) != 2 {
267			t.Fatalf("candidate count = %d, want 2", len(rc.Candidates))
268		}
269		for _, c := range rc.Candidates {
270			if c.Result != CandidateLost {
271				t.Fatalf("candidate %s result = %s, want lost", c.BlockID, c.Result)
272			}
273			var wantVoter []byte
274			switch c.BlockID {
275			case local.BlockID:
276				if !c.Local {
277					t.Fatalf("local candidate flag must be retained: %+v", c)
278				}
279				wantVoter = keys[0].pub
280			case altID:
281				wantVoter = keys[1].pub
282			default:
283				t.Fatalf("unexpected candidate %s", c.BlockID)
284			}
285			if len(c.Voters) != 1 || fmt.Sprintf("%x", c.Voters[0]) != fmt.Sprintf("%x", wantVoter) {
286				t.Fatalf("candidate %s original vote not retained: %x", c.BlockID, c.Voters)
287			}
288		}
289	
290		// 新轮次尚未提议：Proposal 不再返回第 2 轮的冻结提议。
291		if p, ok := n.Proposal(); ok {
292			t.Fatalf("round 2 proposal must not be exposed in round 3: %+v", p)
293		}
294	
295		// 逐笔交易：到期轮次不大于新轮次的查为 expired（含共享、竞争独有、候选外），
296		// 未到期的候选交易回到排队，候选外晚到期交易保持排队；都不带确认块关联。
297		for _, x := range txs {
298			info := n.mustTx(t, x.tx.ID())
299			want := StatusQueued
300			if x.tx.Expiry <= newRound {
301				want = StatusExpired
302			}
303			if info.Status != want {
304				t.Fatalf("tx %q status = %s, want %s (expiry %d)",
305					x.tx.Content, info.Status, want, x.tx.Expiry)
306			}
307			if info.BlockHeight != 0 || info.BlockID != "" {
308				t.Fatalf("tx %q must not reference a confirmed block: height=%d block=%q",
309					x.tx.Content, info.BlockHeight, info.BlockID)
310			}
311		}
312	
313		// 账户0：shared(seq2) 过期移出，已确认序号仍为 1，待处理为空。
314		if a := n.Account(keys[0].pub); a.ConfirmedSequence != 1 || len(a.Pending) != 0 {
315			t.Fatalf("account 0 after end = %+v, want confirmed seq 1 with no pending", a)
316		}
317		// 账户1：本地独有交易晚到期，回到排队等待打包；序号不推进、无缺口。
318		assertAccountQueue(t, n, keys[1].pub, 0, map[string]string{txs[1].tx.ID(): "waiting-pack"})
319		// 账户2：竞争独有交易恰好到期，移出待处理，查为过期；序号不推进。
320		if a := n.Account(keys[2].pub); a.ConfirmedSequence != 0 || len(a.Pending) != 0 {
321			t.Fatalf("account 2 after end = %+v, want no pending tx", a)
322		}
323		// 账户3：共享的晚到期交易回到排队，两个候选只留下一个池位、待处理恰一笔。
324		assertAccountQueue(t, n, keys[3].pub, 0, map[string]string{txs[3].tx.ID(): "waiting-pack"})
325		// 账户4：候选外早到期交易移出，晚到期交易仍排队；序号缺口（缺 seq1）照常指出。
326		assertAccountQueue(t, n, keys[4].pub, 0, map[string]string{txs[5].tx.ID(): "waiting-pack"})
327		if a := n.Account(keys[4].pub); a.Gap != 1 {
328			t.Fatalf("account 4 gap after end = %d, want 1", a.Gap)
329		}
330	}
331	
332	// TestEndRoundSaveFailureAtomic 覆盖主动结束未确认轮次保存失败的完整回归序列：
333	// 失败整体回滚（返回轮次为 0，内存/磁盘/重开三处一致）-> 恢复后在原轮次再次
334	// 结束才进入下一轮，落选标记、交易回排队（共享一份）、过期与不留块全部生效并
335	// 再次持久化。
336	func TestEndRoundSaveFailureAtomic(t *testing.T) {
337		// 前五把密钥中前四把为验证者，第五把仅作交易发送者。
338		keys := genKeys(t, 5)
339		dir := t.TempDir()
340		vals := make([][]byte, 4)
341		for i := range vals {
342			vals[i] = keys[i].pub
343		}
344		n, err := New(dir, Config{Seed: []byte("test-seed-v1"), Validators: vals, MaxTxsPerBlock: maxTestTxs})
345		if err != nil {
346			t.Fatal(err)
347		}
348	
349		// 第 1 轮确认历史：账户0 seq1 上链（高度 1），确认后节点进入第 2 轮。
350		hist := NewTransaction(keys[0].priv, 1, []byte("round1-confirmed"), 5, 100)
351		if _, err := n.Submit(hist); err != nil {
352			t.Fatal(err)
353		}
354		p1, err := n.Propose()
355		if err != nil {
356			t.Fatal(err)
357		}
358		if fmt.Sprint(p1.TxIDs) != fmt.Sprint([]string{hist.ID()}) {
359			t.Fatalf("setup: round 1 proposal = %v, want [%s]", p1.TxIDs, hist.ID())
360		}
361		// 四验证者门槛为 3 票；不能用 confirmCandidate——它按 len(keys) 计票，
362		// 而本测试的 keys[4] 不是验证者。手动投出三张确认票。
363		for i := 0; i < 3; i++ {
364			res, err := n.Vote(keys[i].pub, 1, p1.BlockID)
365			if err != nil || !res.Counted {
366				t.Fatalf("round 1 confirming vote %d: %+v %v", i+1, res, err)
367			}
368			if (i == 2) != res.Confirmed {
369				t.Fatalf("round 1 vote %d confirmed=%v, want %v", i+1, res.Confirmed, i == 2)
370			}
371		}
372		if n.CurrentRound() != 2 || n.Height() != 1 {
373			t.Fatalf("setup: round=%d height=%d, want 2/1", n.CurrentRound(), n.Height())
374		}
375		confirmedBlock, err := n.BlockAt(1)
376		if err != nil {
377			t.Fatal(err)
378		}
379	
380		local, altID, txs := buildRoundTwoPending(t, n, keys)
381		assertRoundTwoPending(t, n, local, altID, txs, confirmedBlock, keys)
382	
383		// 快照结束前的磁盘文件：失败的保存既不得改写它，也不得残留临时文件。
384		statePath := filepath.Join(dir, stateFileName)
385		before, err := os.ReadFile(statePath)
386		if err != nil {
387			t.Fatal(err)
388		}
389	
390		// 主动结束因节点状态写入失败而返回错误：返回轮次必须为 0。
391		n.injectSaveErr = errors.New("disk full (simulated)")
392		nextRound, err := n.EndRound()
393		n.injectSaveErr = nil
394		if err == nil {
395			t.Fatal("EndRound must return an error when saving node state fails")
396		}
397		if reason(err) != "" {
398			t.Fatalf("save failure must surface as an infrastructure error, not a rejection %q: %v", reason(err), err)
399		}
400		if nextRound != 0 {
401			t.Fatalf("EndRound return round = %d, want 0 on save failure", nextRound)
402		}
403	
404		// 内存：轮次、候选、票、未投票名单、提议、每笔交易状态与账户查询全部照旧。
405		assertRoundTwoPending(t, n, local, altID, txs, confirmedBlock, keys)
406	
407		// 磁盘：状态文件逐字节保持操作前内容，目录中仅有 state.json。
408		after, err := os.ReadFile(statePath)
409		if err != nil {
410			t.Fatal(err)
411		}
412		if string(after) != string(before) {
413			t.Fatal("state file changed despite the failed save")
414		}
415		dirEntries, err := os.ReadDir(dir)
416		if err != nil {
417			t.Fatal(err)
418		}
419		var names []string
420		for _, e := range dirEntries {
421			names = append(names, e.Name())
422		}
423		if fmt.Sprint(names) != "[state.json]" {
424			t.Fatalf("failed save must not leave temp files, dir contains %v", names)
425		}
426	
427		// 重开节点：保存记录中没有本次结束造成的任何变化，看到同样的未结束状态。
428		reopened, err := Open(dir)
429		if err != nil {
430			t.Fatal(err)
431		}
432		assertRoundTwoPending(t, reopened, local, altID, txs, confirmedBlock, keys)
433	
434		// 保存恢复正常后，节点仍处于原轮次；再次 EndRound 才进入第 3 轮。
435		nextRound, err = reopened.EndRound()
436		if err != nil {
437			t.Fatalf("EndRound after recovery failed: %v", err)
438		}
439		if nextRound != 3 {
440			t.Fatalf("EndRound after recovery = %d, want 3", nextRound)
441		}
442		assertRoundThreeEnded(t, reopened, local, altID, txs, confirmedBlock, keys)
443	
444		// 成功的结束同样持久化：再开一次看到完全一致的第 3 轮状态。
445		durable, err := Open(dir)
446		if err != nil {
447			t.Fatal(err)
448		}
449		assertRoundThreeEnded(t, durable, local, altID, txs, confirmedBlock, keys)
450	}
