	for i := 0; i < count; i++ {
		res, err := n.Vote(keys[i].pub, round, blockID)
		if err != nil {
			t.Fatalf("vote %d: %v", i, err)
		}
		if i < count-1 && res.Confirmed {
			t.Fatalf("confirmed too early at vote %d", i+1)
